const MALUS_HORS_UE = /* MALUS_HORS_UE — config */ 4;

// --- Normalisation and matching --------------------------------------------

/** Lowercase, no accents: matching is done on this form. */
const norm = (s) =>
  String(s ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * Looks for a term surrounded by non-alphanumerics, so that "ANSSI" does
 * not fire inside another word. Regexes are memoised: ~150 terms are tested
 * against each article.
 */
const RE_CACHE = new Map();
function contains(haystack, term) {
  let re = RE_CACHE.get(term);
  if (!re) {
    re = new RegExp(`(^|[^a-z0-9])${escapeRe(norm(term))}([^a-z0-9]|$)`);
    RE_CACHE.set(term, re);
  }
  return re.test(haystack);
}

// --- Processing ------------------------------------------------------------

const retenus = [];
let ecartesExclusion = 0;
let ecartesScore = 0;

for (const item of $input.all()) {
  const article = item.json;

  // Technical item emitted by collection when no article is kept: it only
  // carries the feed report.
  if (article._empty || !article.title) continue;

  const titreNorm = norm(article.title);
  const texteNorm = norm(`${article.title} ${article.excerpt}`);

  if (EXCLUSIONS.some((t) => contains(texteNorm, t))) {
    ecartesExclusion += 1;
    continue;
  }

  let scoreTotal = 0;
  let signalFaible = false;
  const scoreParAxe = {};
  const themes = [];
  const motsCles = new Set();
  const explication = [];

  const ancreUE = MARQUEURS_UE.some((t) => contains(texteNorm, t));

  for (const [axe, cercles] of Object.entries(AXES)) {
    let scoreAxe = 0;

    for (const [cercle, termes] of Object.entries(cercles)) {
      for (const terme of termes) {
        if (!contains(texteNorm, terme)) continue;

        const dansTitre = contains(titreNorm, terme);
        const points = dansTitre ? POIDS[cercle] * BONUS_TITRE : POIDS[cercle];

        scoreAxe += points;
        motsCles.add(terme);
        explication.push(
          `${terme} (${LIBELLE_CERCLE[cercle]}${dansTitre ? `, title ×${BONUS_TITRE}` : ''}) +${points}`,
        );
        if (cercle === 'signaux') signalFaible = true;
      }
    }

    // Global subject claimed outside the EU: subtract MALUS_HORS_UE from the
    // topic score, without going below zero.
    if (scoreAxe > 0 && AXES_ANCRAGE_UE.has(axe) && !ancreUE) {
      const avant = scoreAxe;
      scoreAxe = Math.max(0, scoreAxe - MALUS_HORS_UE);
      explication.push(`outside EU scope −${avant - scoreAxe}`);
    }

    scoreParAxe[axe] = scoreAxe;
    if (scoreAxe >= SEUIL_AXE) themes.push(axe);
    scoreTotal += scoreAxe;
  }

  if (scoreTotal < SEUIL_MIN) {
    ecartesScore += 1;
    continue;
  }

  retenus.push({
    json: {
      ...article,
      score: scoreTotal,
      themes: themes.length ? themes : ['Transverse'],
      keywords: [...motsCles],
      weakSignal: signalFaible,
      scoreDetail: scoreParAxe,
      scoreExplain: explication,
    },
  });
}

// Most relevant articles first: helps when reading executions and sets the
// database insertion order.
retenus.sort((a, b) => b.json.score - a.json.score);

console.log(
  `Scoring: ${retenus.length} kept · ${ecartesScore} below threshold (${SEUIL_MIN}) · ${ecartesExclusion} excluded`,
);

return retenus;

/**
 * DATABASE INSERT PREPARATION
 *
 * Flattens each article into columns ready for the `articles` table.
 * Arrays (themes, keywords, score_explain) are serialised as Postgres
 * literals, and score_detail as JSON: the Postgres node passes values
 * through as is, so this is where they get formatted.
 *
 * Deduplication is handled by the UNIQUE constraint on dedup_key:
 * re-inserting a known article creates no duplicate and does not overwrite
 * its reading status (ON CONFLICT DO NOTHING in the query).
 */

/**
 * Serialises a JS array as a Postgres literal: {"a","b"}.
 * Inner quotes and backslashes are escaped.
 */
function toPgArray(values) {
  const items = (values ?? [])
    .map((v) => String(v ?? '').trim())
    .filter(Boolean)
    .map((v) => `"${v.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
  return `{${items.join(',')}}`;
}

/** Postgres rejects null bytes, which some badly encoded feeds slip in. */
const clean = (s, max) => {
  const t = String(s ?? '').replace(/\0/g, '').trim();
  return max ? t.slice(0, max) : t;
};

return $input.all().map(({ json: article }) => ({
  json: {
    dedup_key:     clean(article.dedupKey, 500),
    title_vocab:   clean(article.titleVocab, 500),
    title:         clean(article.title, 1000),
    url:           clean(article.url, 2000),
    domain:        clean(article.domain, 255),
    source:        clean(article.source, 255),
    author:        clean(article.author, 255),
    feed:          clean(article.feed, 255),
    category:      clean(article.category, 100),
    source_type:   clean(article.sourceType, 100),
    excerpt:       clean(article.excerpt, 2000),
    published_at:  article.date,
    score:         Number(article.score) || 0,
    weak_signal:   Boolean(article.weakSignal),
    themes:        toPgArray(article.themes),
    keywords:      toPgArray(article.keywords),
    score_detail:  JSON.stringify(article.scoreDetail ?? {}),
    score_explain: toPgArray(article.scoreExplain),
  },
}));

/**
 * COLLECTION LOG
 *
 * Takes the per-feed report produced during collection and flattens it for
 * the `feed_runs` table. Without this trace, a feed that has been dead for
 * three weeks goes unnoticed: the v_sante_flux view relies on it.
 *
 * This node reads the output of the "Collecte des flux" node via the
 * technical key `_feedReport`, carried by the first item.
 */

const items = $('Collecte des flux').all();
const report = items[0]?.json?._feedReport ?? [];

if (!report.length) {
  // No report: nothing to log, don't fail the execution.
  return [];
}

return report.map((entry) => ({
  json: {
    feed:        String(entry.feed ?? '').slice(0, 255),
    status:      entry.status === 'ok' ? 'ok' : 'échec',
    detail:      String(entry.detail ?? '').slice(0, 500),
    items_found: Number(entry.found) || 0,
    items_kept:  Number(entry.kept) || 0,
  },
}));

/**
 * DISCORD MESSAGE
 *
 * Builds the embed sent to the team channel for high-scoring articles.
 * The next node simply POSTs `payload` to the webhook.
 *
 * Discord limits enforced here: title 256 chars, description 4096,
 * field value 1024, footer 2048.
 */

const COULEURS = {
  signalFaible: 0x2ecc71, // green: to keep an eye on
  tresEleve:    0xe74c3c, // red: read first
  eleve:        0x3498db, // blue: normal reading
};

const SEUIL_TRES_ELEVE = /* SEUIL_URGENT — config */ 15;
const SEUIL_ALERTE = /* SEUIL_ALERTE — config */ 8;

/**
 * Escapes Discord markdown. Feed titles/excerpts are untrusted: without this a
 * crafted item could inject a masked link — [ANSSI officiel](https://evil) —
 * or styling into the team channel. Discord consumes the backslash, so escaped
 * text still renders as the plain original.
 */
const escapeMd = (s) => String(s ?? '').replace(/[\\`*_~|[\]()]/g, '\\$&');

/** Truncates cleanly, without leaving half a word. */
function tronquer(texte, max) {
  const s = String(texte ?? '');
  if (s.length <= max) return s;
  const coupe = s.slice(0, max - 1);
  const espace = coupe.lastIndexOf(' ');
  return `${espace > max * 0.6 ? coupe.slice(0, espace) : coupe}…`;
}

const formatDate = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString('en-GB', {
    timeZone: 'Europe/Paris',
    dateStyle: 'medium',
    timeStyle: 'short',
  });
};

return $input.all().map(({ json: article }) => {
  const niveau =
    article.score >= SEUIL_TRES_ELEVE ? 'very high' : article.score >= SEUIL_ALERTE ? 'high' : 'moderate';

  const couleur = article.weakSignal
    ? COULEURS.signalFaible
    : article.score >= SEUIL_TRES_ELEVE
      ? COULEURS.tresEleve
      : COULEURS.eleve;

  // Score breakdown across topics, zero-score topics omitted.
  const repartition = Object.entries(article.scoreDetail ?? {})
    .filter(([, v]) => v > 0)
    .map(([axe, v]) => `**${axe}**: ${v}`)
    .join(' · ');

  const detail = tronquer(
    [repartition, (article.scoreExplain ?? []).join('\n')].filter(Boolean).join('\n'),
    1024,
  );

  return {
    json: {
      payload: {
        embeds: [
          {
            title: tronquer(escapeMd(article.title), 256),
            url: article.url,
            description: tronquer(escapeMd(article.excerpt), 300) || undefined,
            color: couleur,
            fields: [
              { name: '📅 Published', value: formatDate(article.date), inline: true },
              { name: '✍️ Author', value: tronquer(escapeMd(article.author || article.source || '—'), 100), inline: true },
              { name: '📰 Source', value: tronquer(escapeMd(article.source || '—'), 100), inline: true },
              { name: `🎯 Score ${article.score} — ${niveau}`, value: detail || '—' },
            ],
            footer: {
              text: tronquer(
                `${(article.themes ?? []).join(' · ')}`
                + `${article.weakSignal ? ' · 🌱 weak signal' : ''}`
                + ' · scale: core 3 · periphery 2 · signal 1 · ×2 if in title',
                2048,
              ),
            },
            timestamp: article.date,
          },
        ],
      },
    },
  };
});
